/******************************************************************************
 * 函数功能: 填充椭圆
 * 输入参数: 无
 * 输出参数: 无
 * 返回值  : SV_SUCCESS - 成功
             SV_FAILURE - 其它错误
 * 说明    : 无
 *****************************************************************************/
sint32 gui_draw_1million()
{
    uint16 u16mask;
    sint32 s32Ret;
    int len = (sizeof(point_data) / sizeof(point_data[0])) / 2;
    MEDIA_GUI_DRAW_S stMediaGuiDraw;
    MEDIA_GUI_POINT_S stPoint = {0};
    MEDIA_GUI_NULL_S stGuiNull;
    MSG_PACKET_S stMsgPkt = {0};
    int i;

    memset(&stMsgPkt, 0, sizeof(stMsgPkt));
    stMsgPkt.pu8Data = (uint8*)&stMediaGuiDraw;
    stMsgPkt.u32Size = sizeof(MEDIA_GUI_DRAW_S);

    memset(&stMediaGuiDraw, 0x00, sizeof(stMediaGuiDraw));
    u16mask = MEDIA_GUI_GET_MASK(0, MEDIA_GUI_PLANE_OVERLAY, MEDIA_GUI_OP_CLEAR);
    s32Ret = MEDIA_GUI_INSERT(stMediaGuiDraw, u16mask, stGuiNull);
    if (SV_SUCCESS != s32Ret)
    {
        print_level(SV_ERROR, "MEDIA_GUI_INSERT failed. [err=%#x]\n", s32Ret);
    }

    u16mask = MEDIA_GUI_GET_MASK(0, MEDIA_GUI_PLANE_OVERLAY, MEDIA_GUI_OP_DRAW_POINT);
    for(i = 0; i < len; i++)
    {
        stPoint.x = (1.0 * point_data[2*i] / 960);
        stPoint.y = (1.0 * point_data[2*i+1] / 544);
        s32Ret = MEDIA_GUI_INSERT(stMediaGuiDraw, u16mask, stPoint);
        
        if (SV_SUCCESS != s32Ret)   /* 说明buffer已经满了 */
        {
            print_level(SV_ERROR, "[i%d] MEDIA_GUI_INSERT failed! [err=%d]\n", i, s32Ret);            
            break;
        }
    }

    /* 事件提交 */
    s32Ret = Msg_submitEvent(EP_CONTROL, OP_EVENT_MEDIA_GUI, &stMsgPkt);
    if (SV_SUCCESS != s32Ret)
    {
        print_level(SV_ERROR, "Msg_submitEvent failed. [err=%#x]\n", s32Ret);
    }
    
    return SV_SUCCESS;
}

int print_help()
{
    printf("Press\n");
    printf("h: get help info.\n");
    printf("q: exit.\n");
    printf("1: clear plane.\n");
    printf("2: draw line.\n");
    printf("3: draw rect.\n");
    printf("4: fill rect.\n");
    printf("5: draw circle.\n");
    printf("6: fill circle.\n");
    printf("7: fill ellipse.\n");
    printf("8: draw string.\n");
    printf("9: paint 10000 points\n");
    return 0;
}


int main(int argc, char **argv)
{
    sint32 s32Ret;
    char chChoice;

    s32Ret = MSG_SysInit(SV_FALSE);
    if (SV_SUCCESS != s32Ret)
    {
        print_level(SV_ERROR, "MSG_SysInit failed. [err=%#x]\n", s32Ret);
        return -1;
    }
    

    
    printf("Press h to get help info.\n");
    printf("input:");
    do
    {
        
        chChoice = tolower(getchar());
        if (chChoice == 'q')
        {
            break;
        }

        if (chChoice == '\n')
        {
            continue;
        }

        switch(chChoice)
        {
            case '1':
                gui_clear_plane();
                break;
            case '2':
                gui_draw_line();
                break;
            case '3':
                gui_draw_rect();
                break;
            case '4':
                gui_fill_rect();
                break;
            case '5':
                gui_draw_circle();
                break;
            case '6':
                gui_fill_circle();
                break;
            case '7':
                gui_fill_ellipse();
                break;
            case '8':
                gui_draw_string();
                break;
            case '9':
                gui_draw_1million();
                break;
            case 'h':
                print_help();
                break;
            case '\n':
                break;
            default:
                printf("cannot parse command, please press 'h' to get more information.\n");
                break;
        }
        printf("input:");
    } while(1);

    return 0;
}

